## kernels/dex/ssm_update.dx
def dot (n: Nat) (a: Fin n => Float) (b: Fin n => Float) : Float =
  sum (for i. a.i * b.i)

def ssm_step (n m: Nat)
             (x: Fin m => Float)
             (state: Fin n => Float)
             (A: Fin n => (Fin n => Float))
             (B: Fin n => (Fin m => Float))
  : (Fin n => Float) =
  for i. max 0.0 (dot n A.i state + dot m B.i x)  -- ReLU

def ssm_roll (T n m: Nat)
             (tokens: Fin T => Int)
             (embed: Int -> (Fin m => Float))
             (A: Fin n => (Fin n => Float))
             (B: Fin n => (Fin m => Float))
  : (Fin n => Float) =
  def loop (t: Nat) (s: Fin n => Float) : (Fin n => Float) =
    if t == T then s
    else loop (t+1) (ssm_step n m (embed tokens.t) s A B)
  loop 0 (for i. 0.0) [7].

## kernels/dex/tt_quant.dx
def clamp1 (x: Float) : Float = max (-1.0) (min 1.0 x)
def quant (bits: Int) (x: Float) : Float =
  let levels = pow 2 bits
  let idx = round (((clamp1 x + 1.0) * 0.5) * (asFloat (levels - 1)))
  ((asFloat idx) / (asFloat (levels - 1))) * 2.0 - 1.0 [7].

## runtime/pony/main.pony
use "collections"
use "time"

actor KV
  let store: Map[String, String] = Map[String, String]

  be put(k: String, v: String) => store(k) = v
  be get(k: String, p: Promise[None], out: OutStream) =>
    try
      let v = store(k)?
      out.print(v)
    else
      out.print("NOT_FOUND")
    end
    p(None)

actor Router
  let out: OutStream
  new create(env: Env) => out = env.out

  be route(prompt: String, p: Promise[String]) =>
    // egyszerű rule-driven példa
    if prompt.lower().contains("magyar") then
      p("HU_EXPERT")
    else
      p("GEN_EXPERT")
    end

actor Main
  new create(env: Env) =>
    env.out.print("Pony actor runtime up")
    let kv = KV
    let rt = Router(env)
    kv.put("hello", "world")
    let pr = Promise[String]
    pr.next[None](env.out~print())
    rt.route("magyar ssm minta", pr) [4][5].

A Pony aktorok per-aktor GC-je és referencia-képességei (reference capabilities) adnak data-race-free alapot a saját orkesztrációhoz, megállás nélküli GC-vel [5].

